import torch
from .loss import compute_loss, data_preprocess
from collections import deque

def evaluate(model, step, loader, Loss, logger=None, device='cpu'):
    loss_sum = 0
    with torch.no_grad():
        for data, labels, _ in loader:
            loss = compute_loss(model, data, labels, Loss, device=device)
            loss_sum += loss.item()
    loss_mean = loss_sum / len(loader)

    message = "Validation Step {}, Loss: {:.4f}".format(step, loss_mean)

    if logger is not None:
        logger.add_scalar("Loss", loss_mean, step)

    return message, loss_mean

def max_continuous_num(lst: list, target) -> int:
    max_num = cur_num = 0
    for i in lst:
        if i == target:
            cur_num += 1
        else:
            if cur_num > max_num:
                max_num = cur_num
            cur_num = 0
    if cur_num > max_num:
        max_num = cur_num
    return max_num

def mean_filtering_1d(lst: list, kernel_size: int) -> None:
    bias = (kernel_size + 1) // 2
    lg = len(lst)
    window = deque(lst[:bias])

    for i in range(lg):
        if len(window) > kernel_size:
            window.popleft()
        lst[i] = sum(window) / len(window)
        if bias + i < lg:
            window.append(lst[bias+i])
        else:
            window.popleft()

def e2e_evaluate(data, model, max_inject_num=5, kernel_size=5):
    data = data_preprocess(data, device=model.device)
    predictions = model(data)

    predictions = [predictions[i][0].detach().item() for i in range(predictions.size(0))]

    mean_filtering_1d(predictions, kernel_size=kernel_size)
    predictions = [0 if i > 0 else 1 for i in predictions]
    max_inject_num = max_continuous_num(predictions, 1)

    pred = 0
    if max_inject_num > 5:
        pred = 1

    return pred

