import torch


SYSTEM_PROMPT = "You are a helpful assistant. Answer the user's request."


@dataclass(frozen=True)
class EncodedPrompt:
    model_inputs: dict[str, torch.Tensor]
    context_token_indices: list[int]
    context_offsets: list[tuple[int, int]]
    rendered_text: str


def encode_prompt(tokenizer, user_input: str, context: str, max_length: int) -> EncodedPrompt:
    placeholder = f"EXTERNAL_CONTEXT_{uuid4().hex}"
    messages = [
        {"role": "system", "content": SYSTEM_PROMPT},
        {
            "role": "user",
            "content": (
                f"{user_input}\n\n<external_context>\n{placeholder}\n</external_context>"
            ),
        },
    ]
    rendered = tokenizer.apply_chat_template(
        messages,
        tokenize=False,
        add_generation_prompt=True,
    )
    context_start = rendered.find(placeholder)
    if context_start < 0:
        raise ValueError("The tokenizer chat template did not preserve the external context")
    rendered = (
        rendered[:context_start]
        + context
        + rendered[context_start + len(placeholder) :]
    )
    context_end = context_start + len(context)

    encoded = tokenizer(
        rendered,
        return_tensors="pt",
        return_offsets_mapping=True,
        truncation=True,
        max_length=max_length,
        add_special_tokens=False,
    )
    offsets = encoded.pop("offset_mapping")[0].tolist()
    context_token_indices: list[int] = []
    context_offsets: list[tuple[int, int]] = []
    for token_index, (token_start, token_end) in enumerate(offsets):
        if token_end <= token_start:
            continue
        overlap_start = max(token_start, context_start)
        overlap_end = min(token_end, context_end)
        if overlap_start < overlap_end:
            context_token_indices.append(token_index)
            context_offsets.append(
                (overlap_start - context_start, overlap_end - context_start)
            )

    if not context_token_indices:
        raise ValueError(
            "No external-context tokens remain after tokenization. "
            "Increase max_input_tokens or provide a non-empty context."
        )
    return EncodedPrompt(
        model_inputs=dict(encoded),
        context_token_indices=context_token_indices,
        context_offsets=context_offsets,
        rendered_text=rendered,
    )


def labels_for_span(offsets: list[tuple[int, int]], span: tuple[int, int]) -> list[int]:
    span_start, span_end = span
    return [
        int(token_start < span_end and token_end > span_start)
        for token_start, token_end in offsets
    ]


def merge_flagged_spans(
    offsets: list[tuple[int, int]], predictions: list[int]
) -> list[tuple[int, int]]:
    ranges: list[tuple[int, int]] = []
    for (start, end), flagged in zip(offsets, predictions, strict=True):
        if not flagged:
            continue
        if ranges and start <= ranges[-1][1] + 1:
            ranges[-1] = (ranges[-1][0], max(ranges[-1][1], end))
        else:
            ranges.append((start, end))
    return ranges


def redact_spans(text: str, spans: list[tuple[int, int]]) -> str:
    for start, end in reversed(spans):
        text = text[:start] + "[REDACTED UNTRUSTED CONTENT]" + text[end:]
    return text

import torch


def extract_context_features(
    attentions: tuple[torch.Tensor, ...] | list[torch.Tensor],
    context_token_indices: list[int],
    sequence_length: int,
) -> torch.Tensor:
    """Pool attention received by each context token across context query tokens."""
    if not attentions:
        raise RuntimeError(
            "The model returned no attention weights; use eager attention and "
            "enable output_attentions."
        )
    if not context_token_indices:
        raise ValueError("At least one context token is required")

    query_indices = torch.tensor(context_token_indices, dtype=torch.long)
    layer_features = []
    for layer_index, attention in enumerate(attentions):
        if attention.ndim != 4 or attention.shape[0] != 1:
            raise ValueError(
                f"Expected one-example attention shaped [1, heads, query, key], "
                f"got {tuple(attention.shape)} at layer {layer_index}"
            )
        if attention.shape[-2] != sequence_length or attention.shape[-1] != sequence_length:
            raise ValueError(
                "Expected full prompt attention. The model may have returned "
                "cached decoding attention instead."
            )
        query_indices = query_indices.to(attention.device)
        context_attention = attention[0].index_select(1, query_indices)
        context_attention = context_attention.index_select(2, query_indices)
        # [heads, context queries, context keys] -> [context keys, heads]
        layer_features.append(context_attention.float().mean(dim=1).transpose(0, 1))

    features = torch.cat(layer_features, dim=1)
    positions = torch.linspace(
        0.0, 1.0, steps=len(context_token_indices), device=features.device
    ).unsqueeze(1)
    return torch.cat((features, positions), dim=1).cpu().contiguous()

import json
from pathlib import Path
from typing import Any


def load_records(path: Path) -> list[dict[str, Any]]:
    with path.open(encoding="utf-8") as file:
        if path.suffix.lower() == ".jsonl":
            records = [json.loads(line) for line in file if line.strip()]
        else:
            records = json.load(file)

    if isinstance(records, dict):
        records = [records]
    if not isinstance(records, list) or not records:
        raise ValueError(f"Expected a non-empty JSON array or JSONL file: {path}")
    if any(not isinstance(record, dict) for record in records):
        raise ValueError(f"Every dataset entry must be a JSON object: {path}")
    return records


def require_task_fields(
    record: dict[str, Any], index: int
) -> tuple[str, str, str | None]:
    required = ("user_input", "external_context")
    missing = [key for key in required if not isinstance(record.get(key), str)]
    if missing:
        raise ValueError(f"Dataset entry {index} is missing string field(s): {', '.join(missing)}")

    instruction = record.get("injected_instruction")
    context = record["external_context"]
    if instruction is not None and not isinstance(instruction, str):
        raise ValueError(
            f"Dataset entry {index} field 'injected_instruction' must be a string when provided"
        )
    if instruction == "":
        instruction = None
    if instruction is not None and instruction not in context:
        raise ValueError(
            f"Dataset entry {index} injected_instruction must appear inside external_context"
        )
    return record["user_input"], context, instruction

